changeSet.sql:
CREATE TABLE bng.baseline_trees (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    ref text,
    geom geometry(MultiPoint, 27700) NOT NULL
);

CREATE INDEX idx_baseline_trees_project_id
    ON bng.baseline_trees (project_id);

CREATE INDEX idx_baseline_trees_geom
    ON bng.baseline_trees USING GIST (geom);

CREATE TABLE bng.post_intervention_trees (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    ref text,
    geom geometry(MultiPoint, 27700) NOT NULL
);

CREATE INDEX idx_post_intervention_trees_project_id
    ON bng.post_intervention_trees (project_id);

CREATE INDEX idx_post_intervention_trees_geom
    ON bng.post_intervention_trees USING GIST (geom);
